{
  "a_sentences": [
    {
      "a_text": "L'article 8a OPre exige une évaluation du besoin effectuée par des professionnels de la santé, suivie d'une transmission immédiate du résultat à l'auteur de l'ordre ou de la prescription médicale.",
      "b_propositions": ["P3", "P4"]
    },
    {
      "a_text": "Les dispositions applicables en matière de soins ambulatoires externes à l'hôpital prévoient qu'un ordre ou une prescription médicale claire est nécessaire pour la prise en charge des prestations, laquelle doit précéder la réalisation des mesures.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Il n'appartient pas aux médecins de différer indûment l'émission de leur ordre après réception de l'évaluation du besoin.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que l'obligation de prise en charge par l'assurance-maladie débute avec l'ordre médical, une simple validation rétroactive des prestations déjà fournies ne suffisant pas.",
      "b_propositions": ["P6", "P7"]
    },
    {
      "a_text": "La recourante soutient que la prise d'emploi de la personne soignante le 1er janvier 2023 devrait faire débuter la prise en charge, mais l'intimée objecte que l'évaluation du besoin n'était pas conforme à l'article 8a OPre avant le 16 mars 2023 et que l'ordre médical du 27 avril 2023 constitue le point de départ.",
      "b_propositions": ["P2", "P3", "P6", "P7", "P2", "P3", "P6", "P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la date de l'ordre médical du 27 avril 2023 est déterminante pour le début de la prise en charge, indépendamment de la date de l'évaluation du besoin ou de l'engagement de la personne soignante.",
      "b_propositions": ["P6", "P7"]
    }
  ]
}
